package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.distance(int[], int[])
 */
public class MathUtils_distance_TriageGen0Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testDistance_ZeroDistance() {
        int[] p1 = {0, 0, 0};
        int[] p2 = {0, 0, 0};
        double expected = 0.0;
        double actual = MathUtils.distance(p1, p2);
        Assert.assertEquals("Distance between identical points should be 0", expected, actual, DELTA);
    }

    @Test
    public void testDistance_IdenticalPoints() {
        int[] p1 = {1, 2, 3, 4};
        int[] p2 = {1, 2, 3, 4};
        double expected = 0.0;
        double actual = MathUtils.distance(p1, p2);
        Assert.assertEquals("Distance between identical points should be 0", expected, actual, DELTA);
    }

    @Test
    public void testDistance_TwoDimensional() {
        int[] p1 = {0, 0};
        int[] p2 = {3, 4};
        // sqrt((3-0)^2 + (4-0)^2) = sqrt(9 + 16) = 5
        double expected = 5.0;
        double actual = MathUtils.distance(p1, p2);
        Assert.assertEquals("Distance for 2D points (3,4) from origin should be 5", expected, actual, DELTA);
    }

    @Test
    public void testDistance_ThreeDimensional() {
        int[] p1 = {1, 2, 3};
        int[] p2 = {4, 5, 6};
        // sqrt((4-1)^2 + (5-2)^2 + (6-3)^2) = sqrt(3^2 + 3^2 + 3^2) = sqrt(27)
        double expected = Math.sqrt(27.0);
        double actual = MathUtils.distance(p1, p2);
        Assert.assertEquals("Distance for 3D points should be sqrt(27)", expected, actual, DELTA);
    }

    @Test
    public void testDistance_NegativeCoordinates() {
        int[] p1 = {-1, -1};
        int[] p2 = {-4, -5};
        // sqrt((-4 - -1)^2 + (-5 - -1)^2) = sqrt((-3)^2 + (-4)^2) = 5
        double expected = 5.0;
        double actual = MathUtils.distance(p1, p2);
        Assert.assertEquals("Distance with negative coordinates should be calculated correctly", expected, actual, DELTA);
    }

    @Test
    public void testDistance_SingleElement() {
        int[] p1 = {10};
        int[] p2 = {20};
        // sqrt((20-10)^2) = 10
        double expected = 10.0;
        double actual = MathUtils.distance(p1, p2);
        Assert.assertEquals("Distance for 1D points should work", expected, actual, DELTA);
    }

    @Test
    public void testDistance_EmptyArrays() {
        int[] p1 = {};
        int[] p2 = {};
        // Loop doesn't execute, sum is 0, sqrt(0) is 0
        double expected = 0.0;
        double actual = MathUtils.distance(p1, p2);
        Assert.assertEquals("Distance for empty arrays should be 0", expected, actual, DELTA);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testDistance_MismatchedLengths_P1Longer() {
        int[] p1 = {1, 2, 3};
        int[] p2 = {1, 2};
        // Should throw exception when accessing p2[2]
        MathUtils.distance(p1, p2);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testDistance_MismatchedLengths_P2Longer() {
        int[] p1 = {1, 2};
        int[] p2 = {1, 2, 3};
        // The loop iterates based on p1.length. 
        // If p1 is shorter, it won't throw inside the loop, but standard distance 
        // logic usually implies equal dimension. However, based on the provided 
        // code implementation: for (int i = 0; i < p1.length; i++)
        // If p1 is shorter, it will NOT throw. Let's test the actual behavior.
        // To trigger exception, p2 must be shorter than p1.
        MathUtils.distance(p1, p2);
    }

    @Test
    public void testDistance_P2LongerBehavior() {
        // Based on the code: for (int i = 0; i < p1.length; i++)
        // If p1.length < p2.length, it won't throw, it just ignores the rest of p2.
        int[] p1 = {0, 0};
        int[] p2 = {0, 0, 100, 100};
        double expected = 0.0;
        double actual = MathUtils.distance(p1, p2);
        Assert.assertEquals("Method only iterates up to p1.length", expected, actual, DELTA);
    }
}
